CREATE OR REPLACE FUNCTION public.category_key(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT nullif(btrim(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(t, '')),
    '[^[:alnum:][:space:]]+', ' ', 'g'), '\yand\y', ' ', 'g'), '(\w{3,})s\y', '\1', 'g'), '\s+', ' ', 'g')), '')
$function$;

CREATE OR REPLACE FUNCTION public.enforce_company_card_not_reimbursable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.payment_method = 'Company Card' THEN
    IF TG_OP = 'INSERT'
       OR NEW.payment_method IS DISTINCT FROM OLD.payment_method
       OR NEW.reimbursable IS DISTINCT FROM OLD.reimbursable THEN
      NEW.reimbursable := false;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.jsonb_arr(j jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT CASE WHEN jsonb_typeof(j) = 'array' THEN j ELSE '[]'::jsonb END $function$;

CREATE OR REPLACE FUNCTION public.log_ddl_command()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM pg_event_trigger_ddl_commands() LOOP
    -- triggers and policies carry no schema of their own, so they are matched on the table they belong to
    IF (coalesce(r.schema_name, '') = 'public' OR r.object_identity ILIKE '% on public.%') AND NOT r.in_extension THEN
      INSERT INTO system_logs (category, action, target, detail, actor_email, source)
      VALUES ('schema', r.command_tag, r.object_identity, left(current_query(), 1500), session_user::text, 'database');
    END IF;
  END LOOP;
EXCEPTION WHEN OTHERS THEN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.log_ddl_drop()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM pg_event_trigger_dropped_objects() LOOP
    IF r.original AND (coalesce(r.schema_name, '') = 'public' OR r.object_identity ILIKE '% on public.%') AND NOT r.is_temporary THEN
      INSERT INTO system_logs (category, action, target, detail, actor_email, source)
      VALUES ('schema', 'DROP ' || upper(r.object_type), r.object_identity, left(current_query(), 1500), session_user::text, 'database');
    END IF;
  END LOOP;
EXCEPTION WHEN OTHERS THEN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.log_team_member_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  by_email text;
  by_name  text;
  src      text;
  act      text;
  det      text;
  tgt      text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.changed_by IS NOT NULL AND OLD.changed_at > now() - interval '15 seconds' THEN by_email := OLD.changed_by; END IF;
  ELSIF TG_OP = 'INSERT' THEN
    IF NEW.changed_by IS NOT NULL AND NEW.changed_at > now() - interval '60 seconds' THEN by_email := NEW.changed_by; END IF;
  ELSE
    IF NEW.changed_by IS NOT NULL AND NEW.changed_at IS DISTINCT FROM OLD.changed_at AND NEW.changed_at > now() - interval '60 seconds' THEN by_email := NEW.changed_by; END IF;
  END IF;
  IF by_email IS NOT NULL THEN
    SELECT name INTO by_name FROM team_members WHERE lower(email) = lower(by_email) LIMIT 1;
    src := 'app';
  ELSE
    by_email := 'direct database change';
    src := 'database';
  END IF;

  IF TG_OP = 'INSERT' THEN
    act := 'member_added'; tgt := NEW.email;
    det := concat(NEW.name, ' added as ', NEW.role);
  ELSIF TG_OP = 'DELETE' THEN
    act := 'member_removed'; tgt := OLD.email;
    det := concat(OLD.name, ' removed (was ', OLD.role, ')');
  ELSE
    tgt := NEW.email;
    det := concat_ws('; ',
      CASE WHEN NEW.role IS DISTINCT FROM OLD.role THEN concat('role ', OLD.role, ' to ', NEW.role) END,
      CASE WHEN NEW.can_approve_vendors IS DISTINCT FROM OLD.can_approve_vendors THEN concat('vendor approval ', CASE WHEN NEW.can_approve_vendors THEN 'given' ELSE 'taken away' END) END,
      CASE WHEN NEW.can_approve_pos IS DISTINCT FROM OLD.can_approve_pos THEN concat('PO approval ', CASE WHEN NEW.can_approve_pos THEN 'given' ELSE 'taken away' END) END,
      CASE WHEN NEW.function IS DISTINCT FROM OLD.function THEN concat('function ', coalesce(OLD.function, 'none'), ' to ', coalesce(NEW.function, 'none')) END,
      CASE WHEN NEW.name IS DISTINCT FROM OLD.name THEN concat('name ', OLD.name, ' to ', NEW.name) END,
      CASE WHEN NEW.email IS DISTINCT FROM OLD.email THEN concat('email ', OLD.email, ' to ', NEW.email) END
    );
    IF det = '' THEN RETURN NEW; END IF;      -- nothing worth recording (e.g. only the stamp changed)
    act := CASE WHEN NEW.role IS DISTINCT FROM OLD.role THEN 'role_changed' ELSE 'member_updated' END;
  END IF;

  INSERT INTO system_logs (category, action, target, detail, actor_email, actor_name, source)
  VALUES ('team', act, tgt, det, by_email, by_name, src);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- recording must never stop the change itself
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.next_doc_number(kind text, fy_prefix text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  seq_name text;
  existing_count int;
  next_val int;
  like_pattern text;
BEGIN
  IF kind NOT IN ('PR', 'PO', 'VR') THEN
    RAISE EXCEPTION 'next_doc_number: invalid kind %', kind;
  END IF;
  IF fy_prefix !~ '^[A-Za-z0-9/]{1,20}$' THEN
    RAISE EXCEPTION 'next_doc_number: invalid fy_prefix %', fy_prefix;
  END IF;

  -- Fully lowercased: %I below (CREATE SEQUENCE) case-preserves whatever we
  -- pass it, but to_regclass()/nextval(%L) fold an unquoted-looking string
  -- to lowercase when resolving it — mixed case here would make the two
  -- sides disagree on the sequence's real name and "relation does not
  -- exist" on the very next call (confirmed by testing; harmless for the
  -- current all-digit fy_prefix values like "26/27", but not for kind/
  -- fy_prefix values with letters in general, so normalize unconditionally
  -- rather than relying on today's inputs happening to avoid it).
  seq_name := 'doc_seq_' || lower(kind) || '_' || lower(regexp_replace(fy_prefix, '[^A-Za-z0-9]', '_', 'g'));

  -- CREATE SEQUENCE IF NOT EXISTS is NOT race-free on its own: two sessions
  -- can both see "doesn't exist yet" from their own snapshot and both race
  -- to create it, and the loser gets a hard duplicate-key error instead of
  -- silently no-op'ing (confirmed by testing under real concurrent
  -- connections). The advisory lock below serializes only this
  -- once-per-(kind,fiscal-year) check-and-create — once the sequence
  -- exists, every future call skips straight to nextval(), which Postgres
  -- guarantees is race-free with no locking needed.
  PERFORM pg_advisory_xact_lock(hashtext(seq_name));
  IF to_regclass('public.' || seq_name) IS NULL THEN
    like_pattern := fy_prefix || '-' || kind || '-%';
    IF kind = 'PR' THEN
      SELECT count(*) INTO existing_count FROM purchase_requests WHERE pr_number LIKE like_pattern;
    ELSIF kind = 'PO' THEN
      SELECT count(*) INTO existing_count FROM purchase_orders WHERE po_number LIKE like_pattern;
    ELSE
      SELECT count(*) INTO existing_count FROM vendors WHERE vendor_id LIKE like_pattern;
    END IF;
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START %s', seq_name, existing_count + 1);
  END IF;

  EXECUTE format('SELECT nextval(%L)', seq_name) INTO next_val;
  RETURN fy_prefix || '-' || kind || '-07-' || lpad(next_val::text, 4, '0');
END;
$function$;

CREATE OR REPLACE FUNCTION public.promote_other_category(raw text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  k   text := category_key(raw);
  thr int;
  n   int;
  nm  text;
  builtin text[] := ARRAY['Travel Fare','Lodging and Boarding','Food','Bike Fare','Consultant Fee','Professional Fee',
    'Retainership / Consultancy','Legal Fees','Courier','Service','Staff Welfare','Filing Fees','Furniture and Fixtures',
    'Housekeeping','Leasehold Improvements','Medicine','Relocation Allowance','Repairs and Maintenance',
    'Subscription / Software','Learning and Development','Machinery & Plants','Prize Challenge','Hiring'];
BEGIN
  IF k IS NULL OR length(k) < 3 OR length(btrim(raw)) > 40 THEN RETURN; END IF;
  IF array_length(regexp_split_to_array(k, '\s+'), 1) > 5 THEN RETURN; END IF;
  IF k LIKE 'zoho category%' THEN RETURN; END IF;
  IF k = ANY (ARRAY['other','misc','miscellaneou','general','variou','expense','na','n a','none','nil','test','testing','unknown']) THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM custom_categories WHERE key = k) THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM unnest(builtin) b WHERE category_key(b) = k) THEN RETURN; END IF;

  SELECT coalesce((value->>'threshold')::int, 5) INTO thr FROM system_state WHERE key = 'category_auto';
  thr := greatest(coalesce(thr, 5), 2);

  SELECT (SELECT count(*) FROM expense_details WHERE category = 'Other' AND category_key(sub_category) = k)
       + (SELECT count(*) FROM expense_details e, jsonb_array_elements(jsonb_arr(e.itemized_lines)) l
            WHERE l->>'category' = 'Other' AND category_key(l->>'other') = k)
       + (SELECT count(*) FROM purchase_requests p, jsonb_array_elements(jsonb_arr(p.line_items)) l
            WHERE coalesce(p.status, '') <> 'draft' AND l->>'category' = 'Other' AND category_key(l->>'description') = k)
    INTO n;
  IF n < thr THEN RETURN; END IF;

  -- Named after the most common way people wrote it.
  SELECT s.t INTO nm FROM (
    SELECT btrim(sub_category) t FROM expense_details WHERE category = 'Other' AND category_key(sub_category) = k
    UNION ALL SELECT btrim(l->>'other') FROM expense_details e, jsonb_array_elements(jsonb_arr(e.itemized_lines)) l
      WHERE l->>'category' = 'Other' AND category_key(l->>'other') = k
    UNION ALL SELECT btrim(l->>'description') FROM purchase_requests p, jsonb_array_elements(jsonb_arr(p.line_items)) l
      WHERE coalesce(p.status, '') <> 'draft' AND l->>'category' = 'Other' AND category_key(l->>'description') = k
  ) s GROUP BY s.t ORDER BY count(*) DESC, length(s.t) ASC LIMIT 1;
  nm := coalesce(nm, btrim(raw));
  IF nm = upper(nm) OR nm = lower(nm) THEN nm := initcap(nm); END IF;

  INSERT INTO custom_categories (name, key, source, times_seen, created_by) VALUES (nm, k, 'auto', n, 'system')
  ON CONFLICT (key) DO NOTHING;
  IF NOT FOUND THEN RETURN; END IF;

  INSERT INTO activity_log (entity_type, entity_id, entity_ref, action, to_value, actor_name, note)
  VALUES ('settings', 'categories', nm, 'category_auto_created', nm, 'System',
          'Typed under Other ' || n || ' times, so it is now a category.');
  INSERT INTO expense_notifications (recipient_id, type, message, related_type)
  SELECT email, 'category',
         'New category "' || nm || '" was created automatically after it was typed under Other ' || n ||
         ' times. Add a TDS rule for it in Settings if it needs one.', 'category'
  FROM team_members WHERE role IN ('finance', 'admin');
EXCEPTION WHEN OTHERS THEN
  NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.system_logs_refuse()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'System logs cannot be changed or deleted.';
END $function$;

CREATE OR REPLACE FUNCTION public.trg_promote_other_expense()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l jsonb;
BEGIN
  IF NEW.category = 'Other' AND NEW.sub_category IS NOT NULL THEN PERFORM promote_other_category(NEW.sub_category); END IF;
  FOR l IN SELECT * FROM jsonb_array_elements(jsonb_arr(NEW.itemized_lines)) LOOP
    IF l->>'category' = 'Other' AND coalesce(l->>'other', '') <> '' THEN PERFORM promote_other_category(l->>'other'); END IF;
  END LOOP;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.trg_promote_other_pr()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l jsonb;
BEGIN
  IF coalesce(NEW.status, '') <> 'draft' THEN
    FOR l IN SELECT * FROM jsonb_array_elements(jsonb_arr(NEW.line_items)) LOOP
      IF l->>'category' = 'Other' AND coalesce(l->>'description', '') <> '' THEN PERFORM promote_other_category(l->>'description'); END IF;
    END LOOP;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$;

