-- ============================================================
-- indexes
-- ============================================================

CREATE INDEX IF NOT EXISTS activity_log_created_idx ON public.activity_log USING btree (created_at DESC);
CREATE INDEX IF NOT EXISTS activity_log_entity_idx ON public.activity_log USING btree (entity_type, entity_id);
CREATE INDEX IF NOT EXISTS approval_delegations_delegate_idx ON public.approval_delegations USING btree (lower(delegate_email));
CREATE INDEX IF NOT EXISTS expense_captures_receipt_hash_idx ON public.expense_captures USING btree (receipt_hash) WHERE (receipt_hash IS NOT NULL);
CREATE INDEX IF NOT EXISTS expense_reports_assigned_idx ON public.expense_reports USING btree (assigned_to_email) WHERE (assigned_to_email IS NOT NULL);
CREATE INDEX IF NOT EXISTS expense_vouch_events_expense_idx ON public.expense_vouch_events USING btree (expense_id, created_at);
CREATE INDEX IF NOT EXISTS expense_vouch_events_report_idx ON public.expense_vouch_events USING btree (report_id, created_at);
CREATE INDEX IF NOT EXISTS report_advances_advance_idx ON public.report_advances USING btree (advance_id);
CREATE INDEX IF NOT EXISTS system_logs_category_idx ON public.system_logs USING btree (category, created_at DESC);
CREATE INDEX IF NOT EXISTS system_logs_created_idx ON public.system_logs USING btree (created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS system_logs_ref_uidx ON public.system_logs USING btree (category, ref) WHERE (ref IS NOT NULL);

-- ============================================================
-- views
-- ============================================================

-- ============================================================
-- triggers
-- ============================================================

CREATE TRIGGER promote_other_expense AFTER INSERT OR UPDATE OF category, sub_category, itemized_lines ON expense_details FOR EACH ROW EXECUTE FUNCTION trg_promote_other_expense();
CREATE TRIGGER trg_company_card_not_reimbursable BEFORE INSERT OR UPDATE ON expense_details FOR EACH ROW EXECUTE FUNCTION enforce_company_card_not_reimbursable();
CREATE TRIGGER promote_other_pr AFTER INSERT OR UPDATE OF line_items, status ON purchase_requests FOR EACH ROW EXECUTE FUNCTION trg_promote_other_pr();
CREATE TRIGGER system_logs_no_change BEFORE DELETE OR UPDATE ON system_logs FOR EACH ROW EXECUTE FUNCTION system_logs_refuse();
CREATE TRIGGER system_logs_no_truncate BEFORE TRUNCATE ON system_logs FOR EACH STATEMENT EXECUTE FUNCTION system_logs_refuse();
CREATE TRIGGER team_members_system_log AFTER INSERT OR DELETE OR UPDATE ON team_members FOR EACH ROW EXECUTE FUNCTION log_team_member_change();

